    for unit, rows in units.items():
        kept = [f for f in (rows or []) if _filed_on_or_before(f.get("filed"), as_of)]
        if kept:
            out[unit] = kept
    return out or None


def _filter_facts_as_of(facts, as_of):
    """v4.2.84 (historical reconstruction stand, CARD-14): reconstruct exactly what SEC EDGAR
    publicly showed on `as_of` (YYYY-MM-DD) -- never a peek at a later restatement, never a peek
    at a not-yet-filed fact. Filters on the FILING date (`filed`), not the period end date: a fact
    for FY2020 filed in 2026 was not knowable in 2021, even though its period ended in 2020.

    Returns a NEW dict; the cached companyfacts payload in `_FACTS_CACHE` is never mutated, so a
    later call with a different (or no) as_of sees the full, unfiltered history again.
    """
    if not as_of:
        return facts
    out = {k: v for k, v in facts.items() if k != "facts"}
    out_facts = {}
    for taxonomy, tags in (facts.get("facts") or {}).items():
        out_tax = {}
        for tag, block in (tags or {}).items():
            new_units = _filter_units_as_of((block or {}).get("units"), as_of)
            if new_units:
                out_tax[tag] = dict(block, units=new_units)
        out_facts[taxonomy] = out_tax
    out["facts"] = out_facts
    return out


