def _annual_instant_series(facts, tags, taxonomy="us-gaap"):
    """Fiscal-year-end series for an INSTANT (balance-sheet) concept, e.g. equity -- the
    counterpart to `_annual_merged` for DURATION concepts. Instant facts carry no 'start', so the
    >=300-day duration filter does not apply; annual points are identified by form ('10-K') alone,
    restatement-safe (latest 'filed' wins per end), exactly one tag deep -- see EQUITY_TAGS_COMBINED
    for why this deliberately does NOT gap-fill across tags.

    Returns oldest-first [{end, val, accn, filed, tag}]."""
    by_end = {}
    for tag in tags:
        units = _concept(facts, taxonomy, tag)
        if not units:
            continue
        key = _pick_unit(units)
        if not key:
            continue
        for f in units[key]:
            if not f.get("form", "").startswith("10-K"):
                continue
            end = f.get("end")
            if end is None:
                continue
            filed = f.get("filed", "")
            if end not in by_end or filed > by_end[end]["filed"]:
                by_end[end] = {"end": end, "val": f.get("val"), "accn": f.get("accn"),
                               "filed": filed, "tag": tag}
    return [by_end[k] for k in sorted(by_end)]


def _equity_series(facts):
    """StockholdersEquity, falling back WHOLESALE (never per-year) to the combined tag -- see
    EQUITY_TAGS_COMBINED. Returns (series, used_combined_tag_or_None)."""
    primary = _annual_instant_series(facts, EQUITY_TAGS_PRIMARY)
    if primary:
        return primary, None
    combined = _annual_instant_series(facts, EQUITY_TAGS_COMBINED)
    return combined, (EQUITY_TAGS_COMBINED[0] if combined else None)


def _roe_median_5y(net_income_series, equity_series):
    """ROE for fiscal year Y = net_income(Y) / equity at end of Y, median over the most recent
    (up to) 5 years that have BOTH figures. mandate CARD-14 §4:
      - negative or zero equity in any of those years makes ROE undefined for that year (a
        levered-up-by-buybacks balance sheet, not a profitability signal) -- REFUSE the whole
        median rather than quietly average around it (roe_not_computable: negative_equity);
      - fewer than 3 overlapping annual points is too thin to call a median -- REFUSE
        (roe_not_computable: insufficient_history).
    Returns (median_or_None, reason_or_None, n_points_considered)."""
    ni_by_end = {r["end"]: r["val"] for r in (net_income_series or []) if r.get("val") is not None}
    eq_by_end = {r["end"]: r["val"] for r in (equity_series or []) if r.get("val") is not None}
    ends = sorted(set(ni_by_end) & set(eq_by_end))
    if len(ends) < 3:
        return None, "roe_not_computable: insufficient_history", len(ends)
    window = ends[-5:]
    if any(eq_by_end[e] <= 0 for e in window):
        return None, "roe_not_computable: negative_equity", len(window)
    roes = sorted(ni_by_end[e] / eq_by_end[e] for e in window)
    n = len(roes)
    median = roes[n // 2] if n % 2 else (roes[n // 2 - 1] + roes[n // 2]) / 2.0
    return median, None, len(window)

